const payload = $json.body && typeof $json.body === "object" ? $json.body : $json;
const inputTokens = Number(payload.input_tokens ?? 0);
const promptTokens = Number(payload.prompt_tokens ?? inputTokens);
const attachmentTokens = Number(payload.attachment_tokens ?? 0);
const safePrompt = typeof payload.prompt === "string" ? payload.prompt.trim() : "";
const model = typeof payload.model === "string" ? payload.model.trim() : "";
const estimatorModel = "openrouter/free";
const rawIntent = typeof payload.intent === "string" ? payload.intent.trim() : "Text";
const outputGoalTypes = ["Text", "File", "Image", "Audio", "Video"];
const outputAliases = {
  Chat: "Text",
  Agent: "Text",
  App: "Text",
  Website: "Text",
  MCP: "Text",
  "Report/Document": "File",
  Audiobook: "Audio"
};

function normalizeOutputType(value) {
  if (typeof value !== "string") {
    return "";
  }

  const trimmedValue = value.trim();
  return outputGoalTypes.includes(trimmedValue) ? trimmedValue : (outputAliases[trimmedValue] || "");
}

const outputType = normalizeOutputType(payload.output_type) || normalizeOutputType(rawIntent) || "Text";
const attachments = Array.isArray(payload.input_attachments)
  ? payload.input_attachments.map((attachment) => ({
      type: attachment.type || "file",
      name: attachment.name || "attachment",
      mime_type: attachment.mime_type || "",
      size_bytes: Number(attachment.size_bytes ?? 0),
      pages: Number(attachment.pages ?? 0),
      width: Number(attachment.width ?? 0),
      height: Number(attachment.height ?? 0),
      token_estimate: Number(attachment.token_estimate ?? 0),
      confidence: attachment.confidence || "unknown",
      method: attachment.method || "unknown"
    }))
  : [];
const attachmentSummary = attachments.length
  ? attachments.map((attachment) => {
      const dimensions = attachment.width && attachment.height
        ? ", " + attachment.width + "x" + attachment.height
        : "";
      const pages = attachment.pages ? ", " + attachment.pages + " pages" : "";
      const mimeType = attachment.mime_type ? ", " + attachment.mime_type : "";
      return attachment.type + ": " + attachment.name + mimeType + dimensions + pages + ", " + attachment.token_estimate + " tokens, " + attachment.confidence + " confidence";
    }).join("; ")
  : "none";
const estimatorPrompt = [
  "Target model for pricing: " + model,
  "Estimator route used for this free estimate: " + estimatorModel,
  "Output modality: " + outputType,
  "Input tokens: " + inputTokens,
  "Prompt tokens: " + promptTokens,
  "Attachment tokens: " + attachmentTokens,
  "Attachment summary: " + attachmentSummary,
  "Prompt:",
  safePrompt
].join(String.fromCharCode(10));

return [{
  json: {
    ...payload,
    input_tokens: inputTokens,
    prompt_tokens: promptTokens,
    attachment_tokens: attachmentTokens,
    input_attachments: attachments,
    output_type: outputType,
    model,
    estimator_model: estimatorModel,
    intent: outputType,
    input_price: Number(payload.input_price ?? 0),
    output_price: Number(payload.output_price ?? 0),
    openrouter_request: {
      model: estimatorModel,
      temperature: 0.1,
      max_tokens: 500,
      messages: [
        {
          role: "system",
          content: "You estimate usage for TokenOptimizer. Treat output_type as the authoritative OpenRouter-style output modality and never override it from prompt keywords. Use the target model only as pricing and capability context; do not assume this estimator call is running on the target model. For Text output, estimate realistic generated text tokens. For File, Image, Audio, and Video outputs, set predicted_output tokens to 0 because their output cost is modality based. Return only minified JSON with keys predicted_output, predicted_output_min, predicted_output_max, prediction_confidence, and optimization_tip."
        },
        {
          role: "user",
          content: estimatorPrompt
        }
      ]
    }
  }
}];

const requestPayload = $node["Build Estimator Request"].json;
const raw = $json.choices?.[0]?.message?.content ?? "";
const cleaned = String(raw)
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

const inputTokens = Number(requestPayload.input_tokens ?? 0);
const outputType = requestPayload.output_type || "Text";
const isNonTextOutput = ["File", "Image", "Audio", "Video"].includes(outputType);
const heuristicPrediction = isNonTextOutput ? 0 : Math.max(Math.ceil(inputTokens * 1.2), 256);
const upstreamError = $json.error?.message || $json.error || $json.message || "";

function parseEstimatorJson(value) {
  if (!value) {
    return null;
  }

  try {
    return JSON.parse(value);
  } catch (error) {
    const start = value.indexOf("{");
    const end = value.lastIndexOf("}");

    if (start === -1 || end === -1 || end <= start) {
      return null;
    }

    try {
      return JSON.parse(value.slice(start, end + 1));
    } catch {
      return null;
    }
  }
}

const parsed = parseEstimatorJson(cleaned);
const predictedOutput = Number(parsed?.predicted_output);
const predictedMin = Number(parsed?.predicted_output_min);
const predictedMax = Number(parsed?.predicted_output_max);
const confidence = Number(parsed?.prediction_confidence);
let optimizationTip = typeof parsed?.optimization_tip === "string" && parsed.optimization_tip.trim()
  ? parsed.optimization_tip.trim()
  : "";

if (!optimizationTip) {
  if (upstreamError) {
    optimizationTip = "OpenRouter estimator was unavailable: " + String(upstreamError).slice(0, 180);
  } else if (cleaned) {
    optimizationTip = cleaned.replace(/\s+/g, " ").slice(0, 220);
  } else if (isNonTextOutput) {
    optimizationTip = "Use a modality-compatible model and keep prompt instructions focused on the selected output modality.";
  } else {
    optimizationTip = "Shorten repeated context, state the desired text structure, and choose the smallest model that can preserve required quality.";
  }
}

return [{
  json: {
    input_tokens: inputTokens,
    prompt_tokens: Number(requestPayload.prompt_tokens ?? inputTokens),
    attachment_tokens: Number(requestPayload.attachment_tokens ?? 0),
    input_attachments: requestPayload.input_attachments ?? [],
    output_type: outputType,
    predicted_output: Number.isFinite(predictedOutput) && predictedOutput >= 0 ? Math.ceil(predictedOutput) : heuristicPrediction,
    predicted_output_min: Number.isFinite(predictedMin) && predictedMin >= 0 ? Math.ceil(predictedMin) : undefined,
    predicted_output_max: Number.isFinite(predictedMax) && predictedMax >= 0 ? Math.ceil(predictedMax) : undefined,
    prediction_confidence: Number.isFinite(confidence) ? confidence : undefined,
    optimization_tip: optimizationTip,
    intent: outputType,
    input_price: Number(requestPayload.input_price ?? 0),
    output_price: Number(requestPayload.output_price ?? 0)
  }
}];

const outputType = $json.output_type || "media";
const inputPrice = Number($json.input_price ?? 0);
const inputCost = Number($json.input_tokens ?? 0) * (inputPrice / 1000);
const flatOutputCost = 0.01;

return [{
  json: {
    input_tokens: $json.input_tokens,
    prompt_tokens: $json.prompt_tokens,
    attachment_tokens: $json.attachment_tokens,
    input_attachments: $json.input_attachments ?? [],
    output_type: outputType,
    predicted_output: 0,
    predicted_output_min: 0,
    predicted_output_max: 0,
    estimated_cost: Number((inputCost + flatOutputCost).toFixed(6)),
    optimization_tip: "Flat unit output pricing applied for " + outputType + ". Input cost still includes prompt and local attachment token estimates.",
    prediction_method: "flat_unit_multimodal",
    prediction_confidence: 0.74
  }
}];

const inputCost = Number($json.input_tokens ?? 0) * (Number($json.input_price ?? 0) / 1000);
const outputCost = Number($json.predicted_output ?? 0) * (Number($json.output_price ?? 0) / 1000);

return [{
  json: {
    input_tokens: $json.input_tokens,
    prompt_tokens: $json.prompt_tokens,
    attachment_tokens: $json.attachment_tokens,
    input_attachments: $json.input_attachments ?? [],
    output_type: $json.output_type,
    predicted_output: $json.predicted_output,
    predicted_output_min: $json.predicted_output_min,
    predicted_output_max: $json.predicted_output_max,
    estimated_cost: Number((inputCost + outputCost).toFixed(6)),
    optimization_tip: $json.optimization_tip,
    prediction_confidence: $json.prediction_confidence
  }
}];
